mapper.select:

where  1=1

    and b.user_name = #{userName}


    and  b.phonenumber = #{mobile}


    and a.customer_product_type = #{productType}


    and c.app_id = #{productId}

SELECT b.customer_code ,a.send_flag FROM hyzz_customer a, hyzz_customer_user b WHERE a.customer_code = b.customer_code
and b.user_name = #{userName}
and b.phonenumber = #{phoneNumber}

select a.row_id, a.customer_code, a.customer_name, a.customer_short_name, a.trade_type, a.province_id, a.province_name, a.city_id, a.city_name, a.county_id, a.county_name, a.street_id, a.street_name, a.customer_address, a.contact_name, a.contact_phone, a.main_business, a.remark, a.channel_type, a.channel_code, a.channel_name, a.customer_status, a.active_flag, a.create_by, a.create_time, a.impower_type, a.databaseName, a.datasource, a.ext1, a.ext2, a.send_flag, a.send_time, a.sender, a.v_id, a.use_state, b.play_user, c.user_name, c.nick_name, c.phonenumber, c.del_flag, b.account_type, c.password, a.customer_source, b.customer_product_type, b.valid_date, d.use_status from hyzz_customer a left join hyzz_customer_user_mapping b on b.customer_id = a.row_id left join hyzz_customer_user c on c.user_id = b.user_id left join hyzz_customer_application d on d.customer_code = a.customer_code
a.active_flag = 1 and b.customer_product_type = #{productType}
and c.user_name = #{username}
and c.phonenumber = #{phoneNumber}
and d.app_id = #{productId}
